import type {
  FindCatalogItemPricesParams,
  FindCatalogItemsParams,
  FindCatalogAccessesParams,
  CatalogItem,
  CatalogItemPrice,
  CatalogItemPricePage,
  CatalogItemRef,
  CatalogItemStatus,
  CatalogAccess,
  CatalogAccessLevel,
  CatalogChannels,
  CatalogItemBatchOperation,
  CatalogCopyResult,
  Schedule,
  CopyCatalogParams,
  CatalogReadOptions,
  CatalogAudience,
  FindCatalogsParams,
  GetCatalogByKeyParams,
  Catalog,
  CreateCatalogParams,
  CreateCatalogItemParams,
  CreateCatalogAccessParams,
  DeleteCatalogParams,
  DeleteCatalogItemParams,
  DeleteCatalogAccessParams,
  EpochMilliseconds,
  SellableRef,
  StorefrontCustomerGroup,
  StorefrontPrice,
  UpdateCatalogItemParams,
  UpdateCatalogParams,
} from "arky-sdk";
import type { createAdmin } from "arky-sdk/admin";
import type * as Public from "arky-sdk/types";

type AssertTrue<T extends true> = T;
type AssertFalse<T extends false> = T;
type RequiredField<T, K extends keyof T> = {} extends Pick<T, K> ? false : true;
type Same<A, B> = [A] extends [B] ? [B] extends [A] ? true : false : false;
type Eshop = ReturnType<typeof createAdmin>["eshop"];

export type CatalogContracts = [
  AssertTrue<Same<Public.Catalog, Catalog>>,
  AssertFalse<"product_id" extends keyof Extract<SellableRef, { type: "product_variant" }> ? true : false>,
  AssertTrue<RequiredField<Extract<SellableRef, { type: "product_variant" }>, "variant_id">>,
  AssertTrue<Same<SellableRef["type"], "product_variant" | "booking_offering" | "customer_group">>,
  AssertTrue<Same<Extract<SellableRef, { type: "customer_group" }>, { type: "customer_group"; customer_group_id: string }>>,
  AssertTrue<RequiredField<Catalog, "market_id">>,
  AssertTrue<Same<Catalog["schedule"], Schedule>>,
  AssertTrue<Same<Schedule, { type: "always" } | { type: "scheduled"; starts_at: EpochMilliseconds; ends_at: EpochMilliseconds | null }>>,
  AssertFalse<"price_list_id" | "assortment_id" | "priority" | "name" | "starts_at" | "ends_at" extends keyof Catalog ? true : false>,
  AssertTrue<RequiredField<CreateCatalogParams, "market_id">>,
  AssertTrue<RequiredField<CreateCatalogParams, "id">>,
  AssertTrue<RequiredField<CreateCatalogParams, "schedule">>,
  AssertFalse<"market_id" extends keyof UpdateCatalogParams ? true : false>,
  AssertTrue<RequiredField<UpdateCatalogParams, "schedule">>,
  AssertTrue<RequiredField<UpdateCatalogParams, "expected_updated_at">>,
  AssertFalse<"key" extends keyof UpdateCatalogParams ? true : false>,
  AssertTrue<Same<NonNullable<FindCatalogsParams["sort_field"]>, "created_at" | "updated_at">>,
  AssertFalse<"key" extends NonNullable<FindCatalogsParams["sort_field"]> ? true : false>,
  AssertFalse<"deleting" extends CreateCatalogParams["status"]["type"] ? true : false>,
  AssertTrue<"deleting" extends Catalog["status"]["type"] ? true : false>,
  AssertTrue<Same<CatalogItem["status"], CatalogItemStatus>>,
  AssertTrue<Same<CatalogItemStatus["type"], "active" | "archived">>,
  AssertTrue<Same<CatalogItem["schedule"], Schedule>>,
  AssertFalse<"item" | "catalog_id" extends keyof UpdateCatalogItemParams ? true : false>,
  AssertTrue<Same<UpdateCatalogItemParams["position"], number>>,
  AssertTrue<RequiredField<UpdateCatalogItemParams, "schedule">>,
  AssertTrue<RequiredField<UpdateCatalogItemParams, "status">>,
  AssertFalse<"position" extends keyof CreateCatalogItemParams ? true : false>,
  AssertTrue<RequiredField<CreateCatalogItemParams, "id">>,
  AssertTrue<RequiredField<CreateCatalogItemParams, "schedule">>,
  AssertTrue<RequiredField<CreateCatalogItemParams, "status">>,
  AssertTrue<Same<CatalogItemRef["type"], "product" | "booking_service" | "customer_group_offering" | "customer_group">>,
  AssertTrue<Same<Extract<CatalogItemRef, { type: "customer_group_offering" }>, { type: "customer_group_offering"; customer_group_offering_id: string }>>,
  AssertTrue<Same<CatalogAudience["type"], "everyone" | "customer_group" | "customer_group_offering" | "customer" | "all_companies" | "company" | "company_location">>,
  AssertTrue<Same<Extract<CatalogAudience, { type: "customer_group_offering" }>, { type: "customer_group_offering"; customer_group_offering_id: string }>>,
  AssertTrue<Same<keyof Eshop["catalogAccess"], "create" | "get" | "find" | "delete">>,
  AssertTrue<Same<keyof Eshop["catalogItem"], "create" | "update" | "get" | "find" | "delete" | "batch">>,
  AssertTrue<Same<keyof Eshop["catalogItemPrice"], "create" | "update" | "get" | "find" | "delete" | "batch">>,
  AssertTrue<Same<Awaited<ReturnType<Eshop["catalogItemPrice"]["find"]>>, CatalogItemPricePage>>,
  AssertTrue<Same<CatalogItemPricePage["items"], CatalogItemPrice[]>>,
  AssertTrue<Same<CatalogItemPricePage["repairing"], number>>,
  AssertTrue<Same<keyof Eshop["catalog"], "find" | "findPurchasable" | "get" | "getByKey" | "create" | "update" | "copy" | "delete">>,
  AssertTrue<Same<Awaited<ReturnType<Eshop["catalogItem"]["batch"]>>, CatalogItem[]>>,
  AssertTrue<Same<CatalogItemBatchOperation["type"], "create" | "update" | "delete">>,
  AssertTrue<RequiredField<Extract<CatalogItemBatchOperation, { type: "create" }>, "id">>,
  AssertTrue<Same<Parameters<Eshop["catalog"]["copy"]>[0], CopyCatalogParams>>,
  AssertTrue<Same<Awaited<ReturnType<Eshop["catalog"]["copy"]>>, CatalogCopyResult>>,
  AssertTrue<Same<CatalogCopyResult["cursor"], string | null>>,
  AssertTrue<RequiredField<CatalogCopyResult, "items_skipped">>,
  AssertTrue<RequiredField<CatalogCopyResult, "prices_skipped">>,
  AssertFalse<RequiredField<CopyCatalogParams, "cursor">>,
  AssertTrue<Same<CatalogChannels, { type: "all" } | { type: "only"; sales_channel_ids: string[] }>>,
  AssertTrue<Same<CatalogAccessLevel["type"], "browse" | "see_prices" | "buy">>,
  AssertTrue<RequiredField<CatalogAccess, "channels">>,
  AssertTrue<RequiredField<CatalogAccess, "level">>,
  AssertTrue<RequiredField<CreateCatalogAccessParams, "channels">>,
  AssertTrue<RequiredField<CreateCatalogAccessParams, "level">>,
  AssertTrue<RequiredField<CreateCatalogAccessParams, "audience">>,
  AssertTrue<Same<CatalogReadOptions["catalog_id"], string>>,
  AssertTrue<Same<Awaited<ReturnType<Eshop["catalogItem"]["delete"]>>, void>>,
  AssertTrue<Same<Awaited<ReturnType<Eshop["catalogAccess"]["delete"]>>, void>>,
  AssertTrue<Same<Awaited<ReturnType<Eshop["catalog"]["delete"]>>, Catalog>>,
  AssertTrue<RequiredField<DeleteCatalogParams, "expected_updated_at">>,
  AssertTrue<RequiredField<DeleteCatalogItemParams, "expected_updated_at">>,
  AssertTrue<RequiredField<DeleteCatalogAccessParams, "expected_updated_at">>,
  AssertTrue<RequiredField<CreateCatalogItemParams, "catalog_id">>,
  AssertTrue<Extract<keyof Eshop, "priceList" | "assortment" | "assortmentItem" | "catalogEntitlement"> extends never ? true : false>,
  AssertFalse<"usage" extends keyof Eshop["catalog"] ? true : false>,
  AssertFalse<"source" extends keyof StorefrontPrice ? true : false>,
  AssertTrue<RequiredField<StorefrontPrice, "catalog_item_price_id">>,
  AssertFalse<"min_quantity" | "max_quantity" extends keyof StorefrontPrice ? true : false>,
  AssertFalse<"price" extends keyof StorefrontCustomerGroup ? true : false>,
  AssertTrue<Same<StorefrontCustomerGroup["catalog_item_id"], string>>,
  AssertFalse<"charge" extends keyof StorefrontCustomerGroup ? true : false>,
  AssertFalse<"purchase_allowed" extends keyof StorefrontCustomerGroup ? true : false>,
  AssertFalse<"draft" extends FindCatalogItemPricesParams["status"] ? true : false>,
  AssertFalse<"amount" extends FindCatalogItemPricesParams["sort_field"] ? true : false>,
  AssertTrue<SellableRef extends NonNullable<FindCatalogItemPricesParams["sellable"]> ? true : false>,
  AssertFalse<{ store_id: string } extends FindCatalogItemPricesParams ? true : false>,
  AssertTrue<{ store_id: string; catalog_item_id: string } extends FindCatalogItemPricesParams ? true : false>,
  AssertTrue<{ store_id: string; sellable: SellableRef } extends FindCatalogItemPricesParams ? true : false>,
  AssertTrue<CatalogItemRef extends NonNullable<FindCatalogItemsParams["item"]> ? true : false>,
  AssertTrue<RequiredField<FindCatalogItemsParams, "catalog_id">>,
  AssertTrue<RequiredField<FindCatalogAccessesParams, "catalog_id">>,
  AssertFalse<"status" extends keyof FindCatalogItemsParams ? true : false>,
  AssertTrue<RequiredField<GetCatalogByKeyParams, "key">>,
  AssertTrue<"deleting" extends FindCatalogsParams["status"] ? true : false>,
  AssertTrue<"market_id" extends keyof FindCatalogsParams ? true : false>,
  AssertTrue<RequiredField<CatalogAccess, "audience">>,
];
